@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#111719;--paper:#f0eee7;--acid:#d5f365;--muted:#a5aaa4;--line:rgba(245,245,230,.16);--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif;--body:'Manrope',sans-serif}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#131a1b;color:var(--paper);font-family:var(--body);touch-action:none}.game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#252e2d}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 34%,rgba(9,14,15,.14) 75%,rgba(8,12,13,.63) 130%),linear-gradient(180deg,rgba(8,13,14,.32),transparent 18%,transparent 74%,rgba(8,13,14,.42)}
.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:94px;padding:22px 4.4%;display:flex;align-items:flex-start;justify-content:space-between;background:linear-gradient(180deg,rgba(11,17,18,.75),transparent)}.brand{display:flex;align-items:center;gap:10px;color:#f5f2e9;text-decoration:none;font:800 13px/11px var(--display);letter-spacing:1.6px}.brand b{color:var(--acid)}.brand-mark{display:grid;place-items:center;width:34px;height:34px;color:var(--acid);border:1px solid rgba(213,243,101,.62);font-size:23px;border-radius:50%}.run-stats{display:flex;gap:36px;margin-left:70px}.stat{display:grid;gap:2px;text-align:center}.stat-label{font:9px var(--mono);letter-spacing:1.5px;color:#c0c5bb}.stat strong{font:700 19px var(--display);letter-spacing:1px}.sound-button{border:1px solid var(--line);background:rgba(11,17,18,.28);color:var(--paper);padding:9px 12px;font:12px var(--mono);letter-spacing:1px}.sound-button span{font-size:9px;color:#c3c6bd;margin-left:4px}
.left-hud{position:absolute;left:4.4%;top:20%;width:205px;z-index:2}.survivor-card{display:flex;align-items:center;gap:12px;margin-bottom:23px}.avatar{position:relative;width:41px;height:41px;border:1px solid rgba(213,243,101,.8);border-radius:50%;display:grid;place-items:center;color:var(--acid);font-size:22px;background:rgba(19,27,24,.6)}.avatar i{position:absolute;width:7px;height:7px;background:var(--acid);right:0;bottom:1px;border-radius:50%;border:2px solid #222b28}.survivor-info{display:flex;flex-direction:column;gap:2px}.eyebrow,.bar-caption,.weapon-chip small,.objective small,.threat-card small{font:9px var(--mono);letter-spacing:1.3px;color:#b1b8ae}.survivor-info strong{font:700 17px var(--display);letter-spacing:.8px}.evolution{font:9px var(--mono);letter-spacing:.8px;color:var(--acid)}.bar-wrap{margin-bottom:13px}.bar-caption{display:flex;justify-content:space-between;margin-bottom:5px}.bar-caption b{font-weight:400;color:#eff0e5}.meter{height:4px;background:rgba(226,230,215,.18);overflow:hidden}.meter i{height:100%;width:100%;display:block;background:var(--acid);transition:width .22s}.health-wrap .meter i{background:#e78368}.xp-wrap .meter i{background:#c9eb6a}.weapon-chip{display:flex;align-items:center;gap:9px;margin-top:24px;padding-top:13px;border-top:1px solid var(--line)}.weapon-chip>span{display:grid;place-items:center;color:var(--acid);font-size:22px;width:28px}.weapon-chip div{display:grid;gap:2px}.weapon-chip small{font-size:8px}.weapon-chip b{font:700 15px var(--display);letter-spacing:1px}.weapon-chip em{margin-left:auto;font:9px var(--mono);color:var(--acid);font-style:normal}
.right-hud{position:absolute;right:4.4%;top:19%;z-index:2;width:196px;text-align:right}.mini-label{font:8px var(--mono);letter-spacing:.65px;color:#bdc0b7;white-space:nowrap}.mini-label b{color:var(--acid);font-weight:400}.pulse-dot,.difficulty-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c7eb69;box-shadow:0 0 10px #c7eb69;margin-right:5px}.objective{margin-top:32px;display:grid;gap:3px}.objective small{font-size:8px}.objective strong{font:800 23px var(--display);letter-spacing:1px}.objective span{font-size:10px;color:#c1c5ba}.threat-card{display:flex;align-items:center;justify-content:flex-end;gap:9px;margin-top:24px;padding-top:12px;border-top:1px solid var(--line)}.threat-icon{font-size:18px;color:#d98772}.threat-card>div:nth-child(2){display:grid;gap:3px;text-align:left}.threat-card small{font-size:8px}.threat-card b{font:700 12px var(--display);letter-spacing:.7px}.threat-bars{display:flex;gap:3px;margin-left:4px}.threat-bars i{width:4px;height:15px;background:#d98772;opacity:.34;transform:skew(-12deg)}.threat-bars i:first-child{opacity:1}.threat-card[data-level="2"] .threat-bars i:nth-child(-n+2),.threat-card[data-level="3"] .threat-bars i:nth-child(-n+3),.threat-card[data-level="4"] .threat-bars i:nth-child(-n+4),.threat-card[data-level="5"] .threat-bars i{opacity:1}.boss-alert{position:absolute;top:106px;left:50%;transform:translateX(-50%);z-index:4;display:none;align-items:center;gap:10px;padding:9px 15px;border:1px solid rgba(242,125,93,.7);background:rgba(39,20,19,.88);color:#f28a6d;box-shadow:0 0 28px rgba(235,85,58,.17)}.boss-alert.show{display:flex;animation:bossPulse 1s infinite alternate}.boss-alert>span{font-size:22px}.boss-alert div{display:grid}.boss-alert small{font:8px var(--mono);letter-spacing:1px}.boss-alert b{font:800 18px var(--display);letter-spacing:1px}.boss-alert em{font:8px var(--mono);font-style:normal;color:#e3baab;margin-left:14px}@keyframes bossPulse{to{box-shadow:0 0 38px rgba(235,85,58,.38)}}
.bottom-hud{position:absolute;z-index:2;bottom:27px;left:4.4%;right:4.4%;display:flex;align-items:center;justify-content:space-between}.tip{font-size:10px;color:#c3c7bc}.tip>span{font-size:16px;color:var(--acid);vertical-align:-2px;margin-right:5px}.tip b{font:9px var(--mono);letter-spacing:1px;color:var(--acid);margin-right:8px}.tip i{font-style:normal}.controls-legend{display:flex;align-items:center;gap:4px;color:#d4d7cc}.controls-legend kbd{font:9px var(--mono);border:1px solid rgba(236,238,222,.38);padding:4px 5px;min-width:20px;text-align:center;border-radius:2px}.controls-legend kbd:nth-of-type(4){margin-right:7px}.controls-legend kbd:nth-of-type(5){margin-left:4px}.controls-legend span{font:8px var(--mono);letter-spacing:.7px;color:#bfc3b8}.controls-legend>i{font-style:normal;color:#777}.mobile-hint{display:none}.joystick,.mobile-pause{display:none}
.overlay{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(10,15,16,.47);backdrop-filter:blur(4px)}.hidden{display:none!important}.intro-overlay{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding-left:14%;background:linear-gradient(90deg,rgba(11,16,17,.91) 0%,rgba(11,16,17,.77) 34%,rgba(11,16,17,.17) 75%,rgba(11,16,17,.12))}.intro-copy{max-width:520px}.pretitle{font:10px var(--mono);letter-spacing:2px;color:#c0c4b8}.pretitle>span{display:inline-block;width:20px;height:1px;background:var(--acid);vertical-align:middle;margin-right:8px}.intro-copy h1{font:900 clamp(76px,10.5vw,142px)/.77 var(--display);letter-spacing:-2px;margin:23px 0 20px;color:#f0eee7}.intro-copy h1 i,.choice-panel h2 i,.pause-panel h2 i{font-style:normal;color:var(--acid)}.intro-copy p{font-size:13px;line-height:1.8;color:#c2c6bb;margin:0}.intro-meta{display:flex;gap:21px;margin-top:24px;font:8px var(--mono);letter-spacing:.65px;color:#d1d3c7}.intro-meta span:first-child{color:#f08d73}.intro-action{margin-top:30px;width:295px}.difficulty{height:46px;display:flex;align-items:center;padding:0 12px;background:rgba(230,235,215,.07);border:1px solid rgba(230,235,215,.16);gap:8px}.difficulty>div{display:grid;gap:2px}.difficulty b{font:9px var(--mono);letter-spacing:1px}.difficulty small{font:8px var(--mono);color:#a7afa5;letter-spacing:.4px}.difficulty-arrow{margin-left:auto;color:var(--acid)}.difficulty-dot{margin:0}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:48px;margin-top:8px;padding:0 16px;border:0;background:var(--acid);color:#19201b;cursor:pointer;font:800 12px var(--display);letter-spacing:1.4px;transition:background .16s,transform .16s}.primary-button:hover{background:#e2ff87;transform:translateY(-2px)}.primary-button b{font:20px var(--body);font-weight:500}.controls-note{display:flex;justify-content:center;gap:8px;margin-top:12px;font:8px var(--mono);color:#c1c4ba;letter-spacing:.5px}.controls-note i{font-style:normal;color:var(--acid)}.version-tag{position:absolute;bottom:25px;left:4.4%;font:8px var(--mono);letter-spacing:1px;color:#89918a}.version-tag i{color:var(--acid);font-style:normal;margin:0 4px}
.choice-overlay{background:rgba(8,13,13,.76);backdrop-filter:blur(8px)}.choice-panel{text-align:center;width:min(760px,92vw)}.level-up-label{font:10px var(--mono);letter-spacing:2px;color:var(--acid)}.level-up-label span{margin:0 8px}.choice-panel h2,.pause-panel h2{font:800 52px/.95 var(--display);letter-spacing:1px;margin:12px 0 8px}.choice-panel>p,.pause-panel>p{margin:0;color:#b9beb4;font-size:12px}.upgrade-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:28px}.upgrade-card{position:relative;min-height:178px;padding:20px 17px;text-align:left;background:rgba(233,237,221,.07);border:1px solid rgba(230,235,215,.22);color:var(--paper);cursor:pointer;transition:.18s}.upgrade-card:hover{transform:translateY(-4px);border-color:var(--acid);background:rgba(213,243,101,.1)}.upgrade-card .card-icon{display:grid;place-items:center;width:37px;height:37px;background:rgba(213,243,101,.12);color:var(--acid);font-size:22px;margin-bottom:15px}.upgrade-card small{font:8px var(--mono);letter-spacing:1.2px;color:var(--acid)}.upgrade-card h3{font:700 21px var(--display);letter-spacing:.5px;margin:4px 0 4px}.upgrade-card p{font-size:10px;line-height:1.5;color:#bac0b5;margin:0}.upgrade-card .card-tag{position:absolute;right:13px;top:13px;font:8px var(--mono);color:#ffb292}.reroll-note{margin-top:19px;font:8px var(--mono);letter-spacing:1.4px;color:#aab1a6}.reroll-note b{color:var(--acid);font-weight:400}.pause-overlay,.end-overlay{background:rgba(8,13,13,.78);backdrop-filter:blur(8px)}.pause-panel,.end-panel{text-align:center;width:min(400px,90vw);padding:36px 40px;background:rgba(26,34,32,.93);border:1px solid rgba(231,237,219,.21)}.pause-symbol{font-size:29px;color:var(--acid)}.pause-panel .pretitle,.end-panel .pretitle{margin-top:13px}.pause-panel h2,.end-panel h2{font-size:47px;margin:10px 0}.pause-panel .primary-button,.end-panel .primary-button{margin-top:23px}.pause-controls{margin-top:17px;font:8px var(--mono);letter-spacing:.7px;color:#9da69b}.end-panel h2{color:#f08d73}.run-summary{display:flex;justify-content:space-around;border-block:1px solid var(--line);padding:14px 0;margin-top:22px}.run-summary>div{display:grid;gap:3px}.run-summary small{font:8px var(--mono);letter-spacing:.7px;color:#adb4a9}.run-summary b{font:700 21px var(--display)}.toast{position:absolute;z-index:5;left:50%;top:24%;transform:translateX(-50%) translateY(-6px);opacity:0;pointer-events:none;padding:9px 15px;background:rgba(14,21,19,.88);border:1px solid rgba(213,243,101,.5);font:10px var(--mono);letter-spacing:.7px;color:var(--acid);transition:.25s}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
@media(max-width:700px){.topbar{height:72px;padding:13px 15px}.brand{font-size:11px;line-height:9px;gap:7px}.brand-mark{width:29px;height:29px;font-size:19px}.run-stats{gap:15px;margin-left:0}.stat-label{font-size:7px;letter-spacing:.8px}.stat strong{font-size:16px}.kills-stat{display:none}.sound-button{padding:7px 8px;font-size:10px}.sound-button span{display:none}.left-hud{top:84px;left:15px;width:149px}.survivor-card{gap:8px;margin-bottom:13px}.avatar{width:31px;height:31px;font-size:17px}.eyebrow{font-size:7px}.survivor-info strong{font-size:14px}.evolution{font-size:7px}.bar-caption{font-size:8px;letter-spacing:.6px}.bar-caption b{font-size:8px}.bar-wrap{margin-bottom:9px}.weapon-chip{margin-top:13px;padding-top:8px;gap:6px}.weapon-chip>span{font-size:17px;width:21px}.weapon-chip small{font-size:7px}.weapon-chip b{font-size:13px}.weapon-chip em{font-size:8px}.right-hud{top:87px;right:15px;width:147px}.mini-label{font-size:6px;letter-spacing:0}.objective{margin-top:20px}.objective small{font-size:7px}.objective strong{font-size:19px}.objective span{font-size:8px}.threat-card{margin-top:15px;gap:6px}.threat-card small{font-size:7px}.threat-card b{font-size:10px}.threat-icon{font-size:15px}.threat-bars i{height:12px;width:3px}.bottom-hud{bottom:15px;left:15px;right:15px}.tip{max-width:58%;font-size:9px}.tip i{font-size:8px}.tip b{font-size:8px;margin-right:4px}.controls-legend{display:none}.mobile-hint{display:block;font:8px var(--mono);letter-spacing:1px;color:#d3d8cc;opacity:.8}.intro-overlay{padding:0 8%;justify-content:center;background:linear-gradient(90deg,rgba(11,16,17,.89),rgba(11,16,17,.45)),linear-gradient(0deg,rgba(11,16,17,.7),transparent)}.intro-copy{margin-top:-55px}.pretitle{font-size:8px;letter-spacing:1.3px}.intro-copy h1{font-size:clamp(74px,18vw,112px);margin:21px 0 15px}.intro-copy p{font-size:11px}.intro-meta{gap:11px;flex-wrap:wrap;font-size:7px;margin-top:17px}.intro-action{width:min(295px,100%);margin-top:22px}.difficulty{height:42px}.primary-button{height:46px}.version-tag{left:15px;bottom:13px;font-size:7px}.joystick{display:block;position:absolute;z-index:3;left:22px;bottom:34px;width:112px;height:112px;opacity:0;pointer-events:none;transition:opacity .2s}.game-shell.playing .joystick{opacity:.83;pointer-events:auto}.joy-ring{position:absolute;inset:0;border:1px solid rgba(234,241,222,.38);background:rgba(16,23,22,.24);border-radius:50%;display:grid;place-items:center;backdrop-filter:blur(2px)}.joy-knob{width:43px;height:43px;background:rgba(213,243,101,.76);border:1px solid #efffbd;border-radius:50%;box-shadow:0 0 15px rgba(213,243,101,.22);transform:translate(0,0)}.mobile-pause{display:grid;place-items:center;position:absolute;z-index:4;right:18px;bottom:41px;width:40px;height:40px;border-radius:50%;border:1px solid rgba(235,239,223,.52);background:rgba(14,20,19,.48);color:white;font-size:17px;opacity:0;pointer-events:none}.game-shell.playing .mobile-pause{opacity:1;pointer-events:auto}.choice-panel h2{font-size:39px}.choice-panel>p{font-size:10px}.upgrade-cards{gap:7px;margin-top:20px}.upgrade-card{padding:12px 10px;min-height:165px}.upgrade-card .card-icon{width:30px;height:30px;font-size:18px;margin-bottom:10px}.upgrade-card small{font-size:7px;letter-spacing:.6px}.upgrade-card h3{font-size:17px}.upgrade-card p{font-size:9px}.reroll-note{font-size:7px}.boss-alert{top:77px;padding:7px 10px;gap:7px}.boss-alert>span{font-size:17px}.boss-alert small{font-size:6px}.boss-alert b{font-size:15px}.boss-alert em{font-size:6px;margin-left:3px}.toast{top:35%;font-size:8px;white-space:nowrap}}
@media(max-height:650px) and (min-width:701px){.intro-copy h1{font-size:95px}.intro-copy h1{margin:14px 0}.intro-action{margin-top:17px}.intro-meta{margin-top:16px}.left-hud,.right-hud{top:17%}.bottom-hud{bottom:15px}}
@media(max-height:620px) and (max-width:700px){.intro-copy{margin-top:-18px}.intro-copy h1{font-size:70px;margin:14px 0 10px}.intro-meta{display:none}.intro-action{margin-top:14px}.intro-copy p{font-size:10px}.left-hud{top:75px}.right-hud{top:78px}.survivor-card{margin-bottom:8px}.objective{margin-top:12px}.threat-card{margin-top:8px}.joystick{width:88px;height:88px;bottom:22px;left:16px}.joy-knob{width:35px;height:35px}.mobile-pause{bottom:30px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {
    timer: $('timer'), wave: $('wave'), kills: $('kills'), health: $('healthText'), healthBar: $('healthBar'),
    xpBar: $('xpBar'), level: $('levelText'), evolution: $('evolution'), weaponName: $('weaponName'),
    weaponLevel: $('weaponLevel'), weaponIcon: $('weaponIcon'), threat: $('threat'), threatCard: document.querySelector('.threat-card'),
    objective: $('objective'), hero: $('heroName'), boss: $('bossAlert'), toast: $('toast')
  };
  const rand = (a,b) => a + Math.random() * (b-a);
  const clamp = (v,a,b) => Math.max(a, Math.min(b,v));
  const TAU = Math.PI * 2;
  let W = innerWidth, H = innerHeight, dpr = 1, last = 0, gameState = 'intro', toastTimer = 0;
  let keys = Object.create(null), joy = {x:0,y:0,active:false}, audioOn = false;
  let player, enemies, bullets, particles, pickups, scenery, elapsed, kills, spawnClock, wave, bossSpawned, shake, aimAngle;
  const upgradePool = [
    {id:'damage',icon:'✹',tag:'POTENCIA',title:'Munición perforante',desc:'Tus disparos hacen un 30% más de daño.',apply:p=>p.damage*=1.3},
    {id:'rate',icon:'⚡',tag:'VELOCIDAD',title:'Dedo en el gatillo',desc:'Dispara un 22% más rápido.',apply:p=>p.fireRate*=.78},
    {id:'health',icon:'✚',tag:'SUPERVIVENCIA',title:'Pulso de adrenalina',desc:'Recupera 35 de salud y gana +15 de salud máxima.',apply:p=>{p.maxHp+=15;p.hp=Math.min(p.maxHp,p.hp+35)}},
    {id:'speed',icon:'➤',tag:'MOVILIDAD',title:'Botas de asalto',desc:'Muévete un 14% más rápido.',apply:p=>p.speed*=1.14},
    {id:'magnet',icon:'◎',tag:'RECURSOS',title:'Imán de chatarra',desc:'Atrae experiencia desde más lejos.',apply:p=>p.magnet+=65},
    {id:'armor',icon:'⬟',tag:'DEFENSA',title:'Chaleco reforzado',desc:'Reduce el daño recibido un 18%.',apply:p=>p.armor=Math.min(.65,p.armor+.18)},
    {id:'multishot',icon:'⠿',tag:'PISTOLA',title:'Doble cañón',desc:'Añade un proyectil extra por disparo.',apply:p=>p.projectiles=Math.min(5,p.projectiles+1)},
    {id:'drone',icon:'◉',tag:'NUEVA ARMA',title:'Dron centinela',desc:'Un dron orbita y dispara a la horda.',apply:p=>p.drones++},
    {id:'shotgun',icon:'✣',tag:'NUEVA ARMA',title:'Escopeta recortada',desc:'Ráfagas de perdigones para corta distancia.',apply:p=>p.shotgun=true},
    {id:'flame',icon:'♨',tag:'NUEVA ARMA',title:'Cóctel incendiario',desc:'Llamas periódicas abrasan a los cercanos.',apply:p=>p.flame=true},
    {id:'crit',icon:'✦',tag:'PRECISIÓN',title:'Punto débil',desc:'12% de probabilidad de daño crítico x2.',apply:p=>p.crit=Math.min(.55,p.crit+.12)},
    {id:'heal',icon:'♥',tag:'SUPERVIVENCIA',title:'Sangre fría',desc:'Regenera 1.2 de salud cada segundo.',apply:p=>p.regen+=1.2}
  ];
  function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize,{passive:true}); resize();
  function reset(){
    player={x:0,y:0,r:14,hp:100,maxHp:100,xp:0,need:7,level:1,speed:190,damage:24,fireRate:.52,fire:0,projectiles:1,armor:0,magnet:125,crit:.05,regen:0,regenClock:0,invuln:0,drones:0,shotgun:false,shotgunClock:1,flame:false,flameClock:3,evo:0};
    enemies=[];bullets=[];particles=[];pickups=[];scenery=[];elapsed=0;kills=0;spawnClock=.3;wave=1;bossSpawned=false;shake=0;aimAngle=0;
    for(let i=0;i<95;i++)scenery.push({x:rand(-1150,1150),y:rand(-900,900),seed:Math.random()});
    updateHud();
  }
  function begin(){reset();gameState='playing';document.querySelector('.game-shell').classList.add('playing');$('introOverlay').classList.add('hidden');$('endOverlay').classList.add('hidden');$('pauseOverlay').classList.add('hidden');last=performance.now()}
  function fmt(t){let n=Math.floor(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
  function updateHud(){
    if(!player)return;
    ui.timer.textContent=fmt(elapsed);ui.wave.textContent=String(wave).padStart(2,'0');ui.kills.textContent=String(kills).padStart(3,'0');
    ui.health.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.healthBar.style.width=(100*player.hp/player.maxHp)+'%';ui.xpBar.style.width=(100*player.xp/player.need)+'%';ui.level.textContent='NIV. '+player.level;
    ui.evolution.textContent=(player.evo===0?'HUMANA':player.evo===1?'CAZADORA':'REINA DE LA HORDA')+' · NIVEL '+player.level;
    ui.hero.textContent=player.evo===0?'LA NÓMADA':player.evo===1?'LA CAZADORA':'LA INDOMABLE';ui.weaponName.textContent=player.shotgun?'ESCOPETA + PISTOLA':'PISTOLA';ui.weaponLevel.textContent='NV. '+(1+Math.floor((player.damage-24)/10));ui.weaponIcon.textContent=player.shotgun?'✣':'✹';
    let intensity=Math.min(5,1+Math.floor(elapsed/35));ui.threatCard.dataset.level=intensity;ui.threat.textContent=['CONTENIDA','INQUIETANTE','PELIGROSA','DESBORDADA','CRÍTICA'][intensity-1];ui.objective.textContent=elapsed>90?'AGUANTA FIRME':elapsed>45?'RESISTE':'SOBREVIVE';
