const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
 console.log('intro:',await page.locator('#introOverlay').isVisible(),'canvas:',await page.locator('#game').evaluate(el=>[el.width,el.height]));
 await page.locator('#startBtn').click();
 await page.waitForTimeout(1200);
 await page.keyboard.down('d');await page.waitForTimeout(650);await page.keyboard.up('d');
 await page.keyboard.press('Space');
 console.log('pause:',await page.locator('#pauseOverlay').isVisible());
 await page.locator('#resumeBtn').click();
 await page.waitForTimeout(2500);
 console.log('choice:',await page.locator('#choiceOverlay').isVisible(),'timer:',await page.locator('#timer').innerText(),'kills:',await page.locator('#kills').innerText());
 if(await page.locator('#choiceOverlay').isVisible()){await page.locator('.upgrade-card').first().click();console.log('upgrade chosen')}
 await page.screenshot({path:'/tmp/opencode/zombie-survival-latest.jpg',type:'jpeg',quality:75});
 console.log('errors:',JSON.stringify(errors));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

