const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({executablePath:'/usr/bin/chromium', headless:true, args:['--no-sandbox','--disable-dev-shm-usage']});
  const page = await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
  const errors=[];
  page.on('pageerror', e=>errors.push(e.message));
  page.on('console', m=>{if(m.type()==='error')errors.push(m.text())});
  await page.goto('http://localhost:3002', {waitUntil:'networkidle'});
  const style = await page.locator('link[href="style.css"]').evaluate(e=>({rules:e.sheet.cssRules.length, selectors:Array.from(e.sheet.cssRules).filter(r=>r.selectorText).map(r=>r.selectorText)}));
  const startVisible = await page.locator('#introOverlay').evaluate(e=>getComputedStyle(e).display!=='none' && getComputedStyle(e).position==='absolute');
  console.log('stylesheet:',style.rules,'selectors:',style.selectors.length,'intro styled:',startVisible);
  await page.screenshot({path:'/tmp/opencode/zombie-survival-latest.jpg',type:'jpeg',quality:75});
  await page.locator('#startBtn').click();
  await page.waitForTimeout(1000);
  await page.keyboard.press('Space');
  const paused=await page.locator('#pauseOverlay').isVisible();
  await page.locator('#resumeBtn').click();
  await page.waitForTimeout(2600);
  const choice=await page.locator('#choiceOverlay').isVisible();
  if(choice) await page.locator('.upgrade-card').first().click();
  console.log('paused:',paused,'upgrade-choice:',choice,'errors:',JSON.stringify(errors));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
